void notify_init( void )
{
	Tsk tsk ; 

	notify_table      = reg_table_create( REG_ATOMIC_USE_RES );
	
	notify_q_free     = q_create();
	notify_q_pennding = q_create();
	
	init_notify_queue:
	{
		UInt8 i ; 
		
		for( i = 0 ; i < NOTIFY_Q ; i ++ )
		{		
			Notify_Msg* msg = (Notify_Msg*)os_mem_request( sizeof( *msg ) );

			q_insert( notify_q_free , (Q_Msg*)msg ) ; 
			q_assign( notify_q_free , (Q_Msg*)msg ) ; 
		}
	}

	
	init_notify_tsk:
	{
		Tsk tsk ; 

		tsk = os_tsk_create( notify_tsk , NOTIFY_PRI , NOTIFY_STK , NULL , "notify_tsk" ); 

		os_tsk_start( tsk , 0 );
	}		
}

